//! Empirical Stress and Trajectory Challenge Test Suite for `crates/flightreader-export`.
//!
//! Stress tests:
//! 1. 50,000+ points continuous trajectory across all 5 export formats (CSV, KML, GPX, GeoJSON, JSON Summary).
//! 2. Rapid altitude climbs and dives (extreme vertical kinematics, negative MSL elevations).
//! 3. Extreme RC stick chatter (Nyquist frequency oscillation, stick saturation).
//! 4. Multi-cell battery drop and brownout (12-cell packs, cell voltage deviation, sudden sag).
//! 5. Massive trajectory time-window filtering and decimation with landmark event pinning.
//! 6. Adversarial boundary conditions (empty, single-point, two-point, string escaping, comms blackout).
//! 7. Streaming telemetry aggregator multi-sensor zero-order hold stress.
//! 8. Streaming performance and memory safety verification.

mod common;

use std::time::Instant;
use common::validator::{assert_kml_coordinates_order, parse_xml, validate_rfc4180};
use flightreader_export::aggregator::TelemetryAggregator;
use flightreader_export::error::ExportError;
use flightreader_export::exporters::{
    export_dataset, CsvDialect, CsvExporter, CsvOptions, ExportFormat, FlightExporter,
    FlightExporterExt, GeoJsonExporter, GeoJsonOptions, GpxExporter, GpxOptions,
    JsonSummaryExporter, JsonSummaryOptions, KmlExporter, KmlOptions, LineEnding,
};
use flightreader_export::filter::{filter_dataset, TimeBound, TimeFilter};
use flightreader_export::model::{
    FlightDataset, FlightEvent, FlightEventType, FlightMetadata, TelemetryPoint,
};

/// Generates a massive, continuous synthetic trajectory containing `point_count` points.
///
/// Features:
/// - 10 Hz telemetry cadence (dt = 0.1s).
/// - Realistic Archimedean spiral geospatial trajectory starting in Seattle (47.6062° N, -122.3321° W).
/// - Complete flight phases: ground idle, takeoff, climb, cruise, turns, high-speed dash, descent, flare, landing.
/// - 4-cell smart battery gradual discharge (100% -> 15%) with cell balance metrics.
/// - Multiple landmark events: Takeoff, Mode Changes, Warnings, MaxAltitude, MaxSpeed, RTH, Landing.
fn generate_massive_trajectory(point_count: usize) -> FlightDataset {
    assert!(point_count >= 1000, "Point count should be >= 1000 for realistic flight phases");

    let base_lat = 47.606212;
    let base_lon = -122.332145;
    let takeoff_alt_msl = 125.40;
    let base_time_ms = 1_729_000_000_000i64;

    let takeoff_idx = 100;
    let landing_idx = point_count.saturating_sub(100);
    let cruise_start = point_count / 10;
    let rth_idx = point_count * 8 / 10;

    let mut points = Vec::with_capacity(point_count);
    let mut events = Vec::new();

    let mut max_alt_agl = 0.0f64;
    let mut max_alt_msl = takeoff_alt_msl;
    let mut max_h_speed = 0.0f64;
    let mut max_v_speed = 0.0f64;
    let mut max_descent = 0.0f64;
    let mut total_distance = 0.0f64;

    let mut prev_lat = base_lat;
    let mut prev_lon = base_lon;

    for i in 0..point_count {
        let elapsed_s = i as f64 * 0.1;
        let is_motor_on = i >= takeoff_idx && i <= landing_idx;
        let fly_time_s = if is_motor_on {
            (i - takeoff_idx) as f64 * 0.1
        } else {
            0.0
        };

        // Altitude profile: climb to 350m AGL, cruise with gentle oscillation, then descend
        let (agl, vel_d) = if i < takeoff_idx {
            (0.0, 0.0)
        } else if i < cruise_start {
            let frac = (i - takeoff_idx) as f64 / (cruise_start - takeoff_idx) as f64;
            (frac * 350.0, -1.5)
        } else if i < rth_idx {
            let phase = ((i - cruise_start) as f64 * 0.005).sin();
            (350.0 + phase * 25.0, phase * 0.5)
        } else if i <= landing_idx {
            let frac = 1.0 - (i - rth_idx) as f64 / (landing_idx - rth_idx) as f64;
            (frac * 350.0, 1.2)
        } else {
            (0.0, 0.0)
        };

        let alt_msl = takeoff_alt_msl + agl;
        let climb_rate = -vel_d;

        // Kinematics and attitude: expanding spiral path
        let angle_rad = (i as f64 * 0.002) % (2.0 * std::f64::consts::PI);
        let radius_deg = (i as f64 * 0.0000008).min(0.05);
        let lat = base_lat + radius_deg * angle_rad.cos();
        let lon = base_lon + (radius_deg * angle_rad.sin()) / base_lat.to_radians().cos();

        let yaw_deg = (angle_rad.to_degrees() + 90.0) % 360.0;
        let heading_deg = if yaw_deg < 0.0 { yaw_deg + 360.0 } else { yaw_deg };

        let h_speed = if is_motor_on {
            12.0 + 3.0 * (i as f64 * 0.01).sin()
        } else {
            0.0
        };
        let speed_3d = (h_speed * h_speed + vel_d * vel_d).sqrt();
        let rad = heading_deg.to_radians();
        let vel_n = h_speed * rad.cos();
        let vel_e = h_speed * rad.sin();

        // Accumulate distance
        if i > 0 {
            let d = flightreader_core::geo::geodesic_distance(prev_lat, prev_lon, lat, lon);
            if d > 0.0 && d < 500.0 {
                total_distance += d;
            }
        }
        prev_lat = lat;
        prev_lon = lon;

        if agl > max_alt_agl { max_alt_agl = agl; }
        if alt_msl > max_alt_msl { max_alt_msl = alt_msl; }
        if h_speed > max_h_speed { max_h_speed = h_speed; }
        if climb_rate > max_v_speed { max_v_speed = climb_rate; }
        if vel_d > max_descent { max_descent = vel_d; }

        let timestamp_utc_ms = base_time_ms + (elapsed_s * 1000.0).round() as i64;
        let timestamp_iso8601 = chrono::DateTime::from_timestamp_millis(timestamp_utc_ms)
            .map(|dt| dt.to_rfc3339_opts(chrono::SecondsFormat::Millis, true))
            .unwrap_or_else(|| "1970-01-01T00:00:00.000Z".to_string());

        // Battery: 100% down to 15%
        let progress = i as f64 / point_count as f64;
        let battery_pct = (100.0 - progress * 85.0).round() as u8;
        let pack_v = 16.8 - progress * 2.8;
        let cell_v_mv = ((pack_v / 4.0) * 1000.0).round() as u16;

        let flight_mode = if i < takeoff_idx {
            "P-GPS".to_string()
        } else if i >= rth_idx && i <= landing_idx {
            "Auto-RTH".to_string()
        } else if i > landing_idx {
            "AutoLanding".to_string()
        } else {
            "P-GPS".to_string()
        };

        let app_warning = if i == point_count / 2 {
            Some("High Wind Warning. Fly with caution.".to_string())
        } else {
            None
        };

        let is_failsafe_active = i >= rth_idx && i <= landing_idx;

        let pt = TelemetryPoint {
            index: i,
            timestamp_utc_ms,
            timestamp_iso8601,
            elapsed_s,
            fly_time_s,
            latitude: lat,
            longitude: lon,
            altitude_msl: alt_msl,
            altitude_agl: agl,
            altitude_baro: agl,
            vps_height_m: if agl < 5.0 { Some(agl) } else { None },
            ground_speed_mps: h_speed,
            speed_3d_mps: speed_3d,
            climb_rate_mps: climb_rate,
            vel_n,
            vel_e,
            vel_d,
            course_deg: heading_deg,
            pitch_deg: if h_speed > 5.0 { -10.5 } else { 0.0 },
            roll_deg: if h_speed > 5.0 { 2.1 } else { 0.0 },
            yaw_deg,
            heading_deg,
            gimbal_pitch_deg: -30.0,
            gimbal_roll_deg: 0.0,
            gimbal_yaw_deg: 0.0,
            gimbal_mode: "Follow Yaw".to_string(),
            rc_aileron: 0.05 * (i as f64 * 0.1).sin(),
            rc_elevator: 0.25,
            rc_throttle: if is_motor_on { 0.55 } else { 0.0 },
            rc_rudder: 0.02 * (i as f64 * 0.05).cos(),
            rc_mode_switch: "P".to_string(),
            rc_signal_quality: 98,
            battery_pct,
            battery_voltage_mv: (pack_v * 1000.0).round() as u32,
            battery_temp_c: 25.0 + progress * 15.0,
            battery_current_a: if is_motor_on { Some(12.4) } else { Some(0.8) },
            cell_voltages_mv: vec![cell_v_mv, cell_v_mv.saturating_sub(5), cell_v_mv + 3, cell_v_mv],
            cell_deviation_mv: 8,
            gps_satellites: 22,
            gps_level: 5,
            flight_mode,
            ground_state: if is_motor_on { "Airborne".to_string() } else { "OnGround".to_string() },
            is_motor_on,
            is_failsafe_active,
            app_warning,
            app_tip: None,
        };
        points.push(pt);
    }

    // Add milestone events
    events.push(FlightEvent {
        timestamp_utc_ms: points[takeoff_idx].timestamp_utc_ms,
        elapsed_s: points[takeoff_idx].elapsed_s,
        flight_time_s: 0.0,
        event_type: FlightEventType::Takeoff,
        description: "Motors armed and takeoff commenced".to_string(),
        message: "Takeoff".to_string(),
        latitude: Some(base_lat),
        longitude: Some(base_lon),
        altitude_msl: Some(takeoff_alt_msl),
    });

    events.push(FlightEvent {
        timestamp_utc_ms: points[rth_idx].timestamp_utc_ms,
        elapsed_s: points[rth_idx].elapsed_s,
        flight_time_s: points[rth_idx].fly_time_s,
        event_type: FlightEventType::RthTriggered,
        description: "Low battery threshold reached, Smart RTH engaged".to_string(),
        message: "RTH Triggered".to_string(),
        latitude: Some(points[rth_idx].latitude),
        longitude: Some(points[rth_idx].longitude),
        altitude_msl: Some(points[rth_idx].altitude_msl),
    });

    events.push(FlightEvent {
        timestamp_utc_ms: points[landing_idx].timestamp_utc_ms,
        elapsed_s: points[landing_idx].elapsed_s,
        flight_time_s: points[landing_idx].fly_time_s,
        event_type: FlightEventType::Landing,
        description: "Aircraft safely touched down".to_string(),
        message: "Landing".to_string(),
        latitude: Some(points[landing_idx].latitude),
        longitude: Some(points[landing_idx].longitude),
        altitude_msl: Some(takeoff_alt_msl),
    });

    let metadata = FlightMetadata {
        log_type: "DJI_TXT_V12".to_string(),
        version: 12,
        app_type: Some("DJIFly".to_string()),
        app_version: Some("1.14.2".to_string()),
        drone_type: Some(77),
        aircraft_model: Some("DJI Mavic 3 Enterprise".to_string()),
        aircraft_name: Some("LongRangeSurveyor-50K".to_string()),
        aircraft_serial: Some("370DF892100000".to_string()),
        camera_serial: Some("CAM981120".to_string()),
        rc_serial: Some("RC8821034".to_string()),
        battery_serial: Some("BAT449102".to_string()),
        start_time_utc: Some(points[0].timestamp_iso8601.clone()),
        start_time_utc_ms: base_time_ms,
        end_time_utc: Some(points.last().unwrap().timestamp_iso8601.clone()),
        duration_seconds: points.last().unwrap().elapsed_s,
        flight_duration_seconds: (landing_idx - takeoff_idx) as f64 * 0.1,
        total_distance_meters: total_distance,
        max_altitude_agl_m: max_alt_agl,
        max_altitude_msl_m: max_alt_msl,
        takeoff_elevation_msl_m: takeoff_alt_msl,
        max_horizontal_speed_mps: max_h_speed,
        max_vertical_speed_mps: max_v_speed,
        max_descent_speed_mps: max_descent,
        home_latitude: Some(base_lat),
        home_longitude: Some(base_lon),
        home_altitude_msl: Some(takeoff_alt_msl),
        rth_altitude_m: Some(50.0),
        total_records: point_count,
        photos_count: Some(150),
        video_time_seconds: Some(2400),
    };

    FlightDataset {
        metadata,
        points,
        events,
    }
}

// =========================================================================
// TEST 1: Massive 50,000+ points continuous trajectory across all 5 formats
// =========================================================================

#[test]
fn test_massive_50k_trajectory_all_exporters() {
    const N: usize = 52_000;
    println!("Generating {} synthetic flight trajectory points...", N);
    let t0 = Instant::now();
    let ds = generate_massive_trajectory(N);
    println!("Generated {} points in {:.2?}", N, t0.elapsed());

    assert_eq!(ds.points.len(), N);
    assert_eq!(ds.metadata.total_records, N);

    // 1. CSV Standard Export Verification
    {
        println!("Exporting {} points to CSV (Standard)...", N);
        let t_csv = Instant::now();
        let exporter = CsvExporter::default();
        let bytes = exporter.export_to_vec(&ds).expect("CSV export must succeed");
        let dur = t_csv.elapsed();
        let mb = bytes.len() as f64 / (1024.0 * 1024.0);
        println!(
            "CSV export completed: {:.2} MB in {:.2?} ({:.0} points/sec, {:.2} MB/s)",
            mb, dur, N as f64 / dur.as_secs_f64(), mb / dur.as_secs_f64()
        );

        assert!(!bytes.is_empty(), "CSV output must be non-empty");
        let (headers, rows) = validate_rfc4180(&bytes);
        assert_eq!(headers.len(), 46, "CSV header must have exactly 46 canonical columns");
        assert_eq!(rows.len(), N, "CSV row count must match points count exactly");

        // Verify first and last rows
        assert_eq!(rows[0][0], "0", "First row elapsed ms must be 0");
        assert_eq!(rows[N - 1][0], format!("{}", ((N - 1) as f64 * 100.0).round() as u64));
    }

    // 2. CSV Telemetry Overlay Dialect Verification
    {
        println!("Exporting {} points to CSV (Telemetry Overlay)...", N);
        let exporter = CsvExporter::new(CsvOptions {
            dialect: CsvDialect::TelemetryOverlay,
            include_bom: false,
            line_ending: LineEnding::Crlf,
        });
        let bytes = exporter.export_to_vec(&ds).expect("TelemetryOverlay CSV export must succeed");
        let (headers, rows) = validate_rfc4180(&bytes);
        assert_eq!(headers.len(), 14, "Telemetry Overlay header must have 14 columns");
        assert_eq!(rows.len(), N, "Telemetry Overlay row count must match points count");
    }

    // 3. KML 2.2 Export Verification
    {
        println!("Exporting {} points to KML 2.2...", N);
        let t_kml = Instant::now();
        let exporter = KmlExporter::default();
        let bytes = exporter.export_to_vec(&ds).expect("KML export must succeed");
        let dur = t_kml.elapsed();
        let mb = bytes.len() as f64 / (1024.0 * 1024.0);
        println!(
            "KML export completed: {:.2} MB in {:.2?} ({:.0} points/sec, {:.2} MB/s)",
            mb, dur, N as f64 / dur.as_secs_f64(), mb / dur.as_secs_f64()
        );

        let text = std::str::from_utf8(&bytes).expect("KML must be valid UTF-8");
        let doc = parse_xml(text).expect("KML must be well-formed XML");

        let root = doc.root_element();
        assert_eq!(root.tag_name().name(), "kml");
        assert_eq!(
            root.attribute("xmlns"),
            Some("http://www.opengis.net/kml/2.2")
        );

        // Verify placemarks and coordinates presence
        let placemarks: Vec<_> = doc.descendants().filter(|n| n.has_tag_name("Placemark")).collect();
        assert!(!placemarks.is_empty(), "KML must contain Placemarks");

        // Count total coordinates inside all LineStrings
        let mut total_coords = 0;
        for ls in doc.descendants().filter(|n| n.has_tag_name("LineString")) {
            if let Some(coords_node) = ls.children().find(|c| c.has_tag_name("coordinates")) {
                let text = coords_node.text().unwrap_or("");
                total_coords += text.split_whitespace().count();
            }
        }
        assert!(
            total_coords >= N,
            "Total KML LineString vertices ({}) must cover all {} points",
            total_coords, N
        );
    }

    // 4. GPX 1.1 Export Verification
    {
        println!("Exporting {} points to GPX 1.1...", N);
        let t_gpx = Instant::now();
        let exporter = GpxExporter::default();
        let bytes = exporter.export_to_vec(&ds).expect("GPX export must succeed");
        let dur = t_gpx.elapsed();
        let mb = bytes.len() as f64 / (1024.0 * 1024.0);
        println!(
            "GPX export completed: {:.2} MB in {:.2?} ({:.0} points/sec, {:.2} MB/s)",
            mb, dur, N as f64 / dur.as_secs_f64(), mb / dur.as_secs_f64()
        );

        let text = std::str::from_utf8(&bytes).expect("GPX must be valid UTF-8");
        let doc = parse_xml(text).expect("GPX must be well-formed XML");

        let root = doc.root_element();
        assert_eq!(root.tag_name().name(), "gpx");
        assert_eq!(root.attribute("version"), Some("1.1"));
        assert_eq!(root.attribute("creator"), Some("OpenFlightReader"));

        let trkpts: Vec<_> = doc.descendants().filter(|n| n.has_tag_name("trkpt")).collect();
        assert_eq!(trkpts.len(), N, "GPX trackpoint count must match points count exactly");

        // Check first and last trkpt attributes
        let first_trkpt = trkpts[0];
        assert!(first_trkpt.attribute("lat").is_some());
        assert!(first_trkpt.attribute("lon").is_some());
        assert!(first_trkpt.children().any(|c| c.has_tag_name("ele")));
        assert!(first_trkpt.children().any(|c| c.has_tag_name("time")));
        assert!(first_trkpt.children().any(|c| c.has_tag_name("extensions")));
    }

    // 5. GeoJSON Export Verification
    {
        println!("Exporting {} points to RFC 7946 GeoJSON...", N);
        let t_geo = Instant::now();
        let exporter = GeoJsonExporter::new(GeoJsonOptions {
            include_coordinate_properties: true,
            pretty: false,
        });
        let bytes = exporter.export_to_vec(&ds).expect("GeoJSON export must succeed");
        let dur = t_geo.elapsed();
        let mb = bytes.len() as f64 / (1024.0 * 1024.0);
        println!(
            "GeoJSON export completed: {:.2} MB in {:.2?} ({:.0} points/sec, {:.2} MB/s)",
            mb, dur, N as f64 / dur.as_secs_f64(), mb / dur.as_secs_f64()
        );

        let v: serde_json::Value = serde_json::from_slice(&bytes).expect("GeoJSON must parse as JSON");
        assert_eq!(v["type"], "FeatureCollection");

        let bbox = v["bbox"].as_array().expect("GeoJSON must contain 3D bbox");
        assert_eq!(bbox.len(), 6, "3D bbox must have 6 elements [min_lon, min_lat, min_alt, max_lon, max_lat, max_alt]");

        let features = v["features"].as_array().expect("features must be array");
        assert!(features.len() >= 3, "Must contain trajectory line and landmarks");

        let traj = &features[0];
        assert_eq!(traj["geometry"]["type"], "LineString");
        let coords = traj["geometry"]["coordinates"].as_array().expect("LineString coordinates");
        assert_eq!(coords.len(), N, "GeoJSON coordinates must have exactly N tuples");

        // Verify coordinateProperties array lengths
        let coord_props = &traj["properties"]["coordinateProperties"];
        assert_eq!(coord_props["times"].as_array().unwrap().len(), N);
        assert_eq!(coord_props["speeds"].as_array().unwrap().len(), N);
        assert_eq!(coord_props["altitudesAgl"].as_array().unwrap().len(), N);
        assert_eq!(coord_props["batteryPercents"].as_array().unwrap().len(), N);
    }

    // 6. Flight Summary JSON Export Verification
    {
        println!("Exporting {} points to Flight Summary JSON...", N);
        let exporter = JsonSummaryExporter::default();
        let bytes = exporter.export_to_vec(&ds).expect("JSON summary export must succeed");
        let v: serde_json::Value = serde_json::from_slice(&bytes).expect("JSON summary must parse");

        assert_eq!(v["version"], "1.0.0");
        assert_eq!(v["overview"]["totalRecords"], N);
        assert_eq!(v["overview"]["aircraftModel"], "DJI Mavic 3 Enterprise");
        assert!(v["kinematics"]["maxAltitudeMslMeters"].as_f64().unwrap() > 400.0);
        assert!(v["kinematics"]["totalDistanceMeters"].as_f64().unwrap() > 1000.0);
        assert_eq!(v["battery"]["startSocPercent"], 100);
        assert_eq!(v["battery"]["endSocPercent"], 15);
    }

    println!("SUCCESS: 52,000 points verified across all 5 export formats!");
}

// =========================================================================
// TEST 2: Rapid Altitude Climbs & Dives (Extreme Vertical Kinematics)
// =========================================================================

#[test]
fn test_rapid_altitude_climbs_and_dives() {
    let point_count = 10_000;
    let mut ds = generate_massive_trajectory(point_count);

    // Inject violent vertical trajectories:
    // 0..2000: Depression below sea level (-420.0m MSL, Dead Sea)
    // 2000..4000: Extreme rocket climb at +80 m/s up to +8,500m MSL
    // 4000..6000: Stratospheric high-altitude cruise (+8,500m MSL)
    // 6000..8000: Terminal free-fall dive at -65 m/s down to 100m MSL
    // 8000..10000: Emergency flare and ground touchdown
    for (i, pt) in ds.points.iter_mut().enumerate() {
        if i < 2000 {
            pt.altitude_msl = -420.0 + (i as f64 * 0.01);
            pt.altitude_agl = 10.0;
            pt.climb_rate_mps = 0.1;
            pt.vel_d = -0.1;
        } else if i < 4000 {
            let frac = (i - 2000) as f64 / 2000.0;
            pt.altitude_msl = -400.0 + frac * 8900.0; // up to 8500m
            pt.altitude_agl = frac * 8500.0;
            pt.climb_rate_mps = 44.5;
            pt.vel_d = -44.5;
        } else if i < 6000 {
            pt.altitude_msl = 8500.0 + (i as f64 * 0.05).sin() * 50.0;
            pt.altitude_agl = 8500.0;
            pt.climb_rate_mps = 0.0;
            pt.vel_d = 0.0;
        } else if i < 8000 {
            let frac = (i - 6000) as f64 / 2000.0;
            pt.altitude_msl = 8500.0 - frac * 8400.0; // down to 100m
            pt.altitude_agl = 8500.0 - frac * 8400.0;
            pt.climb_rate_mps = -42.0;
            pt.vel_d = 42.0;
        } else {
            pt.altitude_msl = 100.0;
            pt.altitude_agl = 0.0;
            pt.climb_rate_mps = 0.0;
            pt.vel_d = 0.0;
        }
    }

    ds.metadata.takeoff_elevation_msl_m = -420.0;
    ds.metadata.max_altitude_msl_m = 8550.0;
    ds.metadata.max_altitude_agl_m = 8500.0;
    ds.metadata.max_vertical_speed_mps = 44.5;
    ds.metadata.max_descent_speed_mps = 42.0;

    // Test GPX export preserves negative and stratospheric elevations
    let gpx_bytes = GpxExporter::default().export_to_vec(&ds).expect("GPX must export");
    let gpx_text = std::str::from_utf8(&gpx_bytes).expect("GPX UTF-8");
    assert!(gpx_text.contains("<ele>-420.00</ele>"), "GPX must preserve negative elevation below sea level");
    assert!(gpx_text.contains("<ele>8500.00</ele>"), "GPX must preserve stratospheric elevation");

    // Test KML export format
    let kml_bytes = KmlExporter::default().export_to_vec(&ds).expect("KML must export");
    let kml_text = std::str::from_utf8(&kml_bytes).expect("KML UTF-8");
    assert!(kml_text.contains(",-420.00"), "KML must include negative altitude coordinates");
    let doc = parse_xml(kml_text).expect("KML well formed");
    assert!(doc.root_element().has_tag_name("kml"));

    // Test CSV export format
    let csv_bytes = CsvExporter::default().export_to_vec(&ds).expect("CSV must export");
    let (headers, rows) = validate_rfc4180(&csv_bytes);
    assert_eq!(rows.len(), 10_000);
    // Find altitude column
    let msl_col = headers.iter().position(|h| h.contains("altitude_msl")).unwrap();
    assert_eq!(rows[0][msl_col], "-420.00");

    // Test JSON summary
    let json_bytes = JsonSummaryExporter::default().export_to_vec(&ds).expect("JSON must export");
    let v: serde_json::Value = serde_json::from_slice(&json_bytes).unwrap();
    assert!(v["kinematics"]["maxAltitudeMslMeters"].as_f64().unwrap() >= 8500.0);
}

// =========================================================================
// TEST 3: Extreme RC Stick Chatter & Boundary Values
// =========================================================================

#[test]
fn test_extreme_rc_stick_chatter() {
    let point_count = 10_000;
    let mut ds = generate_massive_trajectory(point_count);

    // Full 10 Hz Nyquist frequency stick oscillation (-1.0 to +1.0)
    // plus slight saturation (-1.1 and +1.1) to test integer cast saturation
    for (i, pt) in ds.points.iter_mut().enumerate() {
        let sign = if i % 2 == 0 { 1.0 } else { -1.0 };
        pt.rc_throttle = sign * 1.0;
        pt.rc_rudder = -sign * 1.0;
        pt.rc_elevator = sign * 0.95;
        pt.rc_aileron = -sign * 0.95;

        // Introduce boundary/saturation test on points 500..550
        if (500..550).contains(&i) {
            pt.rc_throttle = 1.25; // Over-saturation: must saturate cleanly without panic
            pt.rc_rudder = -1.25;
        }
    }

    // CSV export must format without panic
    let csv_bytes = CsvExporter::default().export_to_vec(&ds).expect("CSV export must succeed");
    let (headers, rows) = validate_rfc4180(&csv_bytes);
    assert_eq!(rows.len(), 10_000);

    let thr_pct_col = headers.iter().position(|h| h == "RC.throttle [%]").unwrap();
    let thr_raw_col = headers.iter().position(|h| h == "RC.throttleRaw").unwrap();

    // Check alternating sign rows
    assert_eq!(rows[0][thr_pct_col], "100");
    assert_eq!(rows[1][thr_pct_col], "-100");

    // Check saturation behavior on saturated row (row 500)
    // 1024 + 1.25 * 660 = 1849
    let saturated_raw: i32 = rows[500][thr_raw_col].parse().expect("raw integer");
    assert!(saturated_raw > 1684, "Raw throttle value must reflect saturation scale");

    // GPX export with RC telemetry extensions
    let gpx_bytes = GpxExporter::default().export_to_vec(&ds).expect("GPX export must succeed");
    let gpx_text = std::str::from_utf8(&gpx_bytes).expect("GPX UTF-8");
    assert!(gpx_text.contains("<uav:rcThrottle>100</uav:rcThrottle>"));
    assert!(gpx_text.contains("<uav:rcThrottle>-100</uav:rcThrottle>"));
}

// =========================================================================
// TEST 4: Multi-cell Battery Drop & Brownout Simulation
// =========================================================================

#[test]
fn test_multi_cell_battery_drop_and_brownout() {
    let point_count = 10_000;
    let mut ds = generate_massive_trajectory(point_count);

    // 12-cell commercial drone battery pack (e.g. Matrice 300 RTK):
    // Nominal: 12 cells * 3.7V = 44.4V (44,400 mV)
    // Points 0..4000: Healthy balanced 12S pack (3.85V/cell = 3850 mV, deviation 6 mV)
    // Points 4000..6000: Cell 4 begins severe premature collapse (drops to 2.80V), deviation spikes to 1050 mV
    // Points 6000..8000: Full pack voltage sag to 32.0V, SOC collapses 20% -> 5% -> 0% (Brownout), RTH triggers
    // Points 8000..10000: Zero-cell edge case (empty cell array from sensor drop)
    for (i, pt) in ds.points.iter_mut().enumerate() {
        if i < 4000 {
            pt.cell_voltages_mv = vec![3850, 3852, 3848, 3850, 3851, 3849, 3850, 3853, 3848, 3850, 3852, 3849];
            pt.cell_deviation_mv = 5;
            pt.battery_pct = 75;
            pt.battery_voltage_mv = 46_200;
        } else if i < 6000 {
            // Bad cell 4
            pt.cell_voltages_mv = vec![3750, 3752, 3748, 2698, 3751, 3749, 3750, 3753, 3748, 3750, 3752, 3749];
            pt.cell_deviation_mv = 1054;
            pt.battery_pct = 35;
            pt.battery_voltage_mv = 43_950;
            pt.app_warning = Some("Severe Battery Cell Voltage Deviation Detected".to_string());
        } else if i < 8000 {
            // Brownout collapse
            pt.cell_voltages_mv = vec![2800, 2810, 2790, 2100, 2800, 2805, 2795, 2810, 2790, 2800, 2805, 2795];
            pt.cell_deviation_mv = 710;
            pt.battery_pct = 8;
            pt.battery_voltage_mv = 33_000;
            pt.is_failsafe_active = true;
            pt.flight_mode = "Auto-RTH".to_string();
        } else {
            // Sensor comms drop: empty cell vector!
            pt.cell_voltages_mv = Vec::new();
            pt.cell_deviation_mv = 0;
            pt.battery_pct = 2;
            pt.battery_voltage_mv = 31_500;
        }
    }

    // Verify CSV handles 12 cells safely (c1..c4 extract first 4, empty handles gracefully)
    let csv_bytes = CsvExporter::default().export_to_vec(&ds).expect("CSV export must succeed");
    let (headers, rows) = validate_rfc4180(&csv_bytes);
    let dev_col = headers.iter().position(|h| h == "BATTERY.cellDeviation [mV]").unwrap();
    let c1_col = headers.iter().position(|h| h == "BATTERY.cell1Voltage [V]").unwrap();
    let c4_col = headers.iter().position(|h| h == "BATTERY.cell4Voltage [V]").unwrap();

    // Normal balanced phase
    assert_eq!(rows[100][dev_col], "5");
    assert_eq!(rows[100][c1_col], "3.850");

    // Bad cell phase: c4 drops to 2.698V
    assert_eq!(rows[5000][dev_col], "1054");
    assert_eq!(rows[5000][c4_col], "2.698");

    // Empty cell phase: c1..c4 fallback to 0.000 without panic
    assert_eq!(rows[9000][c1_col], "0.000");
    assert_eq!(rows[9000][dev_col], "0");

    // Verify Flight Summary JSON captures extremes
    let json_bytes = JsonSummaryExporter::default().export_to_vec(&ds).expect("JSON summary export");
    let v: serde_json::Value = serde_json::from_slice(&json_bytes).unwrap();
    let bat = &v["battery"];
    assert_eq!(bat["maxCellDeviationMv"], 1054);
    assert!(bat["minPackVoltageVolts"].as_f64().unwrap() <= 33.0);
    assert_eq!(bat["cellCount"], 12);

    // Verify KML segments into Warning and Error styling
    let kml_bytes = KmlExporter::default().export_to_vec(&ds).expect("KML export must succeed");
    let kml_text = std::str::from_utf8(&kml_bytes).unwrap();
    assert!(kml_text.contains("<styleUrl>#LineStyleWarning</styleUrl>"));
    assert!(kml_text.contains("<styleUrl>#LineStyleError</styleUrl>"));
}

// =========================================================================
// TEST 5: Massive Trajectory Filtering & Decimation with Landmark Pinning
// =========================================================================

#[test]
fn test_massive_trajectory_filtering_and_decimation() {
    const N: usize = 50_000;
    let ds = generate_massive_trajectory(N);

    // Case A: Time Window Filtering: start = 500.0s, end = 2500.0s
    // At 10 Hz, this spans 20,001 points (elapsed 500.0s to 2500.0s)
    let filter = TimeFilter::parse(Some("500.0"), Some("2500.0")).expect("Valid time filter");
    let filtered = filter_dataset(&ds, Some(&filter), None).expect("Filter execution");

    assert_eq!(filtered.points.len(), 20_001);
    assert_eq!(filtered.points.first().unwrap().elapsed_s, 500.0);
    assert_eq!(filtered.points.last().unwrap().elapsed_s, 2500.0);
    // Sequential re-indexing
    assert_eq!(filtered.points.first().unwrap().index, 0);
    assert_eq!(filtered.points.last().unwrap().index, 20_000);
    assert_eq!(filtered.metadata.total_records, 20_001);
    assert!((filtered.metadata.duration_seconds - 2000.0).abs() < 1e-3);

    // Case B: Decimation from 10 Hz to 1 Hz (10x downsampling)
    let decimated_1hz = filter_dataset(&ds, None, Some(1.0)).expect("1 Hz decimation");
    let expected_len_approx = N / 10;
    // Allow slight delta due to pinned landmark events (takeoff, RTH, landing, extrema)
    assert!(
        (decimated_1hz.points.len() as isize - expected_len_approx as isize).abs() < 50,
        "1 Hz decimation should produce ~{} points, got {}",
        expected_len_approx,
        decimated_1hz.points.len()
    );

    // Critical invariant: Landmark events must be preserved
    let has_takeoff = decimated_1hz.points.iter().any(|p| p.is_motor_on);
    assert!(has_takeoff, "Takeoff event must be pinned in decimated dataset");

    // Case C: Extreme decimation to 0.1 Hz (100x downsampling -> ~500 points)
    let decimated_01hz = filter_dataset(&ds, None, Some(0.1)).expect("0.1 Hz decimation");
    assert!(decimated_01hz.points.len() < 600);
    assert!(decimated_01hz.points.len() > 400);

    // Re-indexing invariant
    for (i, p) in decimated_01hz.points.iter().enumerate() {
        assert_eq!(p.index, i, "Point index must be contiguous 0..N-1");
    }

    // Verify all 5 exporters can serialize the decimated dataset
    let csv_bytes = CsvExporter::default().export_to_vec(&decimated_01hz).unwrap();
    let (_, rows) = validate_rfc4180(&csv_bytes);
    assert_eq!(rows.len(), decimated_01hz.points.len());

    let kml_bytes = KmlExporter::default().export_to_vec(&decimated_01hz).unwrap();
    parse_xml(std::str::from_utf8(&kml_bytes).unwrap()).unwrap();

    let gpx_bytes = GpxExporter::default().export_to_vec(&decimated_01hz).unwrap();
    parse_xml(std::str::from_utf8(&gpx_bytes).unwrap()).unwrap();

    let geo_bytes = GeoJsonExporter::default().export_to_vec(&decimated_01hz).unwrap();
    let _: serde_json::Value = serde_json::from_slice(&geo_bytes).unwrap();

    let json_bytes = JsonSummaryExporter::default().export_to_vec(&decimated_01hz).unwrap();
    let _: serde_json::Value = serde_json::from_slice(&json_bytes).unwrap();
}

// =========================================================================
// TEST 6: Adversarial Boundary Conditions & Schema Escaping
// =========================================================================

#[test]
fn test_adversarial_boundary_conditions() {
    // 1. Empty Dataset
    let empty_ds = FlightDataset::default();
    assert!(empty_ds.is_empty());

    let csv_empty = CsvExporter::default().export_to_vec(&empty_ds).unwrap();
    let (headers, rows) = validate_rfc4180(&csv_empty);
    assert_eq!(headers.len(), 46);
    assert_eq!(rows.len(), 0);

    let kml_empty = KmlExporter::default().export_to_vec(&empty_ds).unwrap();
    parse_xml(std::str::from_utf8(&kml_empty).unwrap()).expect("Empty KML must be well-formed XML");

    let gpx_empty = GpxExporter::default().export_to_vec(&empty_ds).unwrap();
    parse_xml(std::str::from_utf8(&gpx_empty).unwrap()).expect("Empty GPX must be well-formed XML");

    let geo_empty = GeoJsonExporter::default().export_to_vec(&empty_ds).unwrap();
    let v: serde_json::Value = serde_json::from_slice(&geo_empty).unwrap();
    assert_eq!(v["type"], "FeatureCollection");
    assert_eq!(v["features"].as_array().unwrap().len(), 0);

    let json_empty = JsonSummaryExporter::default().export_to_vec(&empty_ds).unwrap();
    let v: serde_json::Value = serde_json::from_slice(&json_empty).unwrap();
    assert_eq!(v["overview"]["totalRecords"], 0);

    // 2. Single Point Dataset
    let single_ds = {
        let mut ds = generate_massive_trajectory(1000);
        ds.points.truncate(1);
        ds.metadata.total_records = 1;
        ds
    };
    assert_eq!(single_ds.points.len(), 1);

    assert!(CsvExporter::default().export_to_vec(&single_ds).is_ok());
    assert!(KmlExporter::default().export_to_vec(&single_ds).is_ok());
    assert!(GpxExporter::default().export_to_vec(&single_ds).is_ok());
    assert!(GeoJsonExporter::default().export_to_vec(&single_ds).is_ok());
    assert!(JsonSummaryExporter::default().export_to_vec(&single_ds).is_ok());

    // 3. Two-Point Dataset
    let two_point_ds = {
        let mut ds = generate_massive_trajectory(1000);
        ds.points.truncate(2);
        ds.metadata.total_records = 2;
        ds
    };
    assert_eq!(two_point_ds.points.len(), 2);
    assert!(CsvExporter::default().export_to_vec(&two_point_ds).is_ok());
    assert!(KmlExporter::default().export_to_vec(&two_point_ds).is_ok());
    assert!(GpxExporter::default().export_to_vec(&two_point_ds).is_ok());
    assert!(GeoJsonExporter::default().export_to_vec(&two_point_ds).is_ok());
    assert!(JsonSummaryExporter::default().export_to_vec(&two_point_ds).is_ok());

    // 4. Special Characters, XML Injection, CSV Injection Stress
    let special_ds = {
        let mut ds = generate_massive_trajectory(1000);
        ds.metadata.aircraft_model = Some("<Drone & Payload 'X-100' \"Special\">".to_string());
        ds.metadata.aircraft_name = Some("Surveyor \u{1F680} (100% OK & Tested)".to_string());
        for p in &mut ds.points[10..20] {
            p.app_warning = Some("Caution: <script>alert('xss')</script> & \"quoted\", commas, \r\nnewlines".to_string());
            p.app_tip = Some("Tip: <verify & confirm>".to_string());
            p.flight_mode = "Mode \"P-GPS,Sport\" & Auto".to_string();
        }
        ds
    };

    // CSV must properly escape quotes and commas
    let csv_bytes = CsvExporter::default().export_to_vec(&special_ds).unwrap();
    let (_, rows) = validate_rfc4180(&csv_bytes);
    assert!(rows[10][44].contains("<script>alert('xss')</script>"));

    // XML must escape & < > " '
    let kml_bytes = KmlExporter::default().export_to_vec(&special_ds).unwrap();
    parse_xml(std::str::from_utf8(&kml_bytes).unwrap()).expect("KML with special characters must be valid XML");

    let gpx_bytes = GpxExporter::default().export_to_vec(&special_ds).unwrap();
    parse_xml(std::str::from_utf8(&gpx_bytes).unwrap()).expect("GPX with special characters must be valid XML");

    let geo_bytes = GeoJsonExporter::default().export_to_vec(&special_ds).unwrap();
    serde_json::from_slice::<serde_json::Value>(&geo_bytes).expect("GeoJSON with special chars must be valid JSON");

    // 5. Stationary Jitter Hover Stress with KML Jitter Filtering
    let jitter_ds = common::mock_data::high_jitter_hover_dataset(5000);
    let kml_filtered = KmlExporter::new(KmlOptions {
        jitter_filter_m: Some(0.20),
        ..Default::default()
    });
    let bytes = kml_filtered.export_to_vec(&jitter_ds).unwrap();
    let text = std::str::from_utf8(&bytes).unwrap();
    let doc = parse_xml(text).expect("Jitter filtered KML must be valid XML");
    assert!(doc.root_element().has_tag_name("kml"));

    // 6. Comms Blackout Gap Stress (>5s gap splitting GPX track segments)
    let blackout_ds = common::mock_data::comms_blackout_dataset();
    let gpx_bytes = GpxExporter::default().export_to_vec(&blackout_ds).unwrap();
    let doc = parse_xml(std::str::from_utf8(&gpx_bytes).unwrap()).unwrap();
    let segments: Vec<_> = doc.descendants().filter(|n| n.has_tag_name("trkseg")).collect();
    assert_eq!(segments.len(), 2, "GPX should split into exactly 2 track segments on blackout gap");
}

// =========================================================================
// TEST 7: Telemetry Aggregator Multi-Sensor Streaming Ingestion Stress
// =========================================================================

#[test]
fn test_telemetry_aggregator_streaming_stress() {
    let mut agg = TelemetryAggregator::new(None)
        .with_version(12)
        .with_details_start_ms(1_729_000_000_000);

    // Build synthetic raw OSD payload (55 bytes)
    // Structure per `osd.rs`:
    // 0..8: lon radians (f64 LE)
    // 8..16: lat radians (f64 LE)
    // 16..18: height dm (i16 LE)
    // 18..20: x_speed cm/s (i16 LE)
    // 20..22: y_speed cm/s (i16 LE)
    // 22..24: z_speed cm/s (i16 LE)
    // 24..26: pitch 0.1 deg (i16 LE)
    // 26..28: roll 0.1 deg (i16 LE)
    // 28..30: yaw 0.1 deg (i16 LE)
    // 30: fly_state u8
    // 31: flyc_command u8
    // 32: flight_status u8
    // 33: battery u8
    // 34..36: fly_time 0.1s (u16 LE)
    // 36: motor_up u8
    // 37: ground_state u8
    // 38: reserved
    // 39: gps_num u8
    // 40: gps_level u8
    let mut osd_bytes = vec![0u8; 55];

    // Stream 5,000 synthetic OSD records through aggregator
    for i in 0..5000 {
        use byteorder::{ByteOrder, LittleEndian};

        let fly_time_s = if i < 100 { 0.0 } else { (i - 100) as f64 * 0.1 };
        let is_motor_up = i >= 100 && i < 4800;

        let lon_rad = -2.1365 + (i as f64 * 0.000001);
        let lat_rad = 0.6593 + (i as f64 * 0.000001);
        let height_dm = if is_motor_up { 1500i16 } else { 0i16 }; // 150.0m

        LittleEndian::write_f64(&mut osd_bytes[0..8], lon_rad);
        LittleEndian::write_f64(&mut osd_bytes[8..16], lat_rad);
        LittleEndian::write_i16(&mut osd_bytes[16..18], height_dm);
        LittleEndian::write_i16(&mut osd_bytes[18..20], 120); // x_speed 1.2 m/s
        LittleEndian::write_i16(&mut osd_bytes[20..22], 0);
        LittleEndian::write_i16(&mut osd_bytes[22..24], 0);
        LittleEndian::write_i16(&mut osd_bytes[24..26], 0);
        LittleEndian::write_i16(&mut osd_bytes[26..28], 0);
        LittleEndian::write_i16(&mut osd_bytes[28..30], 450); // yaw 45.0 deg

        // Byte 30: bit 3 = motor_up, bits 1..2 = ground_state
        let state_byte = if is_motor_up {
            (1 << 3) // motor_up = 1, ground_state = 0 (Airborne)
        } else {
            (1 << 1) // OnGround = 1
        };
        osd_bytes[30] = state_byte;

        // Byte 32: flight mode = P-GPS (14)
        osd_bytes[32] = 14;

        // Byte 33: battery pct = 90
        osd_bytes[33] = 90;

        // Bytes 34..36: fly_time in 0.1s
        let fly_time_tenths = (fly_time_s * 10.0).round() as u16;
        LittleEndian::write_u16(&mut osd_bytes[34..36], fly_time_tenths);

        // Satellites
        osd_bytes[39] = 18;

        // Ingest OSD record (type 1)
        let pt = agg.process_record(1, &osd_bytes).expect("OSD record ingestion must succeed");
        assert!(pt.is_some(), "OSD record must produce a synchronized point");

        // Periodically inject Home point (type 2) at step 50
        if i == 50 {
            // Home record mock payload (36 bytes)
            let mut home_bytes = vec![0u8; 36];
            LittleEndian::write_f64(&mut home_bytes[0..8], -2.1365);
            LittleEndian::write_f64(&mut home_bytes[8..16], 0.6593);
            LittleEndian::write_f32(&mut home_bytes[16..20], 125.0); // height 125.0m
            home_bytes[20] = 0x01; // is_home_record = 1
            agg.process_record(2, &home_bytes).expect("Home record ingestion");
        }

        // Periodically inject text warning (type 5) at step 2500
        if i == 2500 {
            let warn = b"High Wind Warning\0";
            agg.process_record(5, warn).expect("Warning ingestion");
        }
    }

    let dataset = agg.finish();
    assert_eq!(dataset.points.len(), 5000);
    assert_eq!(dataset.metadata.total_records, 5000);

    // Verify monotonic timestamps
    for j in 1..dataset.points.len() {
        assert!(
            dataset.points[j].timestamp_utc_ms >= dataset.points[j - 1].timestamp_utc_ms,
            "Timestamps must be monotonically increasing"
        );
        assert!(
            dataset.points[j].elapsed_s >= dataset.points[j - 1].elapsed_s,
            "Elapsed seconds must be monotonically increasing"
        );
    }

    // Verify milestone events
    assert!(dataset.events.iter().any(|e| e.event_type == FlightEventType::Takeoff));
    assert!(dataset.events.iter().any(|e| matches!(e.event_type, FlightEventType::Warning { .. })));

    // Verify dataset exports cleanly to all formats
    assert!(CsvExporter::default().export_to_vec(&dataset).is_ok());
    assert!(KmlExporter::default().export_to_vec(&dataset).is_ok());
    assert!(GpxExporter::default().export_to_vec(&dataset).is_ok());
    assert!(GeoJsonExporter::default().export_to_vec(&dataset).is_ok());
    assert!(JsonSummaryExporter::default().export_to_vec(&dataset).is_ok());
}

// =========================================================================
// TEST 8: Streaming Throughput and Memory Safety Stress
// =========================================================================

#[test]
fn test_streaming_throughput_and_memory_safety() {
    const N: usize = 60_000;
    let ds = generate_massive_trajectory(N);

    // Measure serialization throughput across all formats
    let formats = [
        ExportFormat::Csv,
        ExportFormat::Kml,
        ExportFormat::Gpx,
        ExportFormat::GeoJson,
        ExportFormat::Json,
    ];

    for fmt in formats {
        let t0 = Instant::now();
        let mut buf = Vec::new();
        export_dataset(&ds, fmt, &mut buf).expect("Streaming export must succeed");
        let dur = t0.elapsed();
        let mb = buf.len() as f64 / (1024.0 * 1024.0);
        let pts_per_sec = N as f64 / dur.as_secs_f64();
        let mb_per_sec = mb / dur.as_secs_f64();

        println!(
            "Format {:?}: {:.2} MB serialized in {:.2?} ({:.0} pts/s, {:.2} MB/s)",
            fmt, mb, dur, pts_per_sec, mb_per_sec
        );

        // Throughput assertion: even in debug mode, each format must process at least 5,000 points/second
        assert!(
            pts_per_sec >= 5_000.0,
            "Format {:?} throughput {:.0} pts/s below 5,000 pts/s threshold",
            fmt,
            pts_per_sec
        );
        assert!(!buf.is_empty(), "Export buffer must not be empty");
    }
}

